import manifest from "./images.generated.json";

// Generated by scripts/build-images.mjs. Never edit images.generated.json by hand.

export type PhotoName =
  | "hero-justice"
  | "litigation"
  | "contracts"
  | "property"
  | "precautionary"
  | "negotiation"
  | "document"
  | "facade"
  | "textured";

export type LogoName = "logo-h" | "mark-gold";

export interface PhotoMeta {
  widths: number[];
  width: number;
  height: number;
  lqip: string;
}

export interface LogoMeta {
  width: number;
  height: number;
}

export const photo = (name: PhotoName): PhotoMeta => (manifest as unknown as Record<PhotoName, PhotoMeta>)[name];
export const logo = (name: LogoName): LogoMeta => (manifest as unknown as Record<LogoName, LogoMeta>)[name];

export const logoSrc = (name: LogoName) => `/img/${name}.png`;
